269	// digestsReferenced returns the set of object digests referenced by a set of
270	// snapshot entries. Multiple entries may share one digest.
271	func digestsReferenced(entries map[string]Entry) map[string]struct{} {
272		digests := make(map[string]struct{}, len(entries))
273		for _, entry := range entries {
274			digests[entry.Digest] = struct{}{}
275		}
276		return digests
277	}
278	
279	// objectContent is a decoded package object kept in memory during import.
280	type objectContent struct {
281		digest  string
282		size    int64
283		content []byte
284	}
285	
286	// materialize decodes the base64 payloads of every carried object into
287	// memory. Import holds the objects while it stages them; packages are
288	// bounded artifacts meant to be copied between machines.
289	func (p *Package) materialize() ([]objectContent, error) {
290		objects := make([]objectContent, 0, len(p.Objects))
291		// Sort so staging order (and any error message) is deterministic.
292		ordered := append([]PackageObject(nil), p.Objects...)
293		sort.Slice(ordered, func(i, j int) bool { return ordered[i].Digest < ordered[j].Digest })
294		for _, obj := range ordered {
295			content, err := base64.StdEncoding.DecodeString(obj.Data)
296			if err != nil {
297				return nil, fmt.Errorf("object %s: %w", obj.Digest, err)
298			}
299			objects = append(objects, objectContent{digest: obj.Digest, size: obj.Size, content: content})
300		}
301		return objects, nil
302	}
