1	package vault
2	
3	import (
4		"crypto/sha256"
5		"encoding/base64"
6		"encoding/hex"
7		"errors"
8		"fmt"
9		"os"
10		"path/filepath"
11		"reflect"
12		"sort"
13	)
14	
15	// ExportResult summarizes a successful snapshot export.
16	type ExportResult struct {
17		Name    string
18		Entries int
19		Objects int
20	}
21	
22	// ImportResult summarizes a successful snapshot import.
23	type ImportResult struct {
24		Name       string
25		Entries    int
26		NewObjects int
27	}
28	
29	// ExportSnapshot writes the named snapshot, together with the content objects
30	// it needs, to output as a portable package.
31	//
32	// Without a base the package is complete: every referenced object is carried,
33	// and a digest shared by several entries is carried once. With base set to the
34	// name of another snapshot in the same repository, the package still records
35	// the target's complete mapping but only carries objects the base does not
36	// reference; an importer can only apply it on top of an identical base.
37	//
38	// Every object the target references is re-read and checked for recorded size
39	// and SHA-256, including objects omitted from a delta, so a corrupt snapshot
40	// record or a missing/damaged object never produces a successful package.
41	//
42	// The output location is held to the same rules as a download: it must be
43	// outside the source repository (judged on actual locations, through
44	// symlinks, and before the file exists), its parent directory must already
45	// exist, an existing output must be a regular file that is not hard-linked to
46	// any index, snapshot record, lock file, or content object, and the package
47	// is committed through a descriptor pinned to the resolved parent directory,
48	// so a parent swapped for a symlink into the repository while the export runs
49	// is detected at commit time and can never redirect the package onto a
50	// repository file. The package is assembled in memory and written to a
51	// temporary file in that directory before an atomic rename: a failed export
52	// never creates or alters the output file.
53	func (s *Store) ExportSnapshot(name, base, output string) (ExportResult, error) {
54		if err := validateName(name); err != nil {
55			return ExportResult{}, err
56		}
57		if base != "" {
58			if err := validateName(base); err != nil {
59				return ExportResult{}, err
60			}
61		}
62		if output == "" {
63			return ExportResult{}, errors.New("output is required")
64		}
65		// Export reads an existing, initialized repository; it never creates one.
66		// The root and index are checked before taking the lock (withLockOpts
67		// passes createRoot=false so even the root directory is not materialized),
68		// and re-checked while holding the lock.
69		rootInfo, err := os.Stat(s.root)
70		switch {
71		case errors.Is(err, os.ErrNotExist):
72			return ExportResult{}, fmt.Errorf("repository %q does not exist; run init first", s.root)
73		case err != nil:
74			return ExportResult{}, err
75		case !rootInfo.IsDir():
76			return ExportResult{}, fmt.Errorf("repository root %q is not a directory", s.root)
77		}
78		if _, err := os.Stat(s.indexPath()); errors.Is(err, os.ErrNotExist) {
79			return ExportResult{}, fmt.Errorf("repository %q is not initialized; run init first", s.root)
80		} else if err != nil {
81			return ExportResult{}, err
82		}
83		var result ExportResult
84		err = s.withLockOpts(true, false, func() error {
85			if _, err := os.Stat(s.indexPath()); errors.Is(err, os.ErrNotExist) {
86				return fmt.Errorf("repository %q is not initialized; run init first", s.root)
87			} else if err != nil {
88				return err
89			}
90			// Validate the destination before reading any object or staging a
91			// temporary file, and hold the pinned parent directory until commit.
92			absOut, mode, pin, err := s.checkOutputSafe(output)
93			if err != nil {
94				return err
95			}
96			defer pin.Close()
97	
98			target, err := s.loadSnapshotRecord(name)
99			if err != nil {
100				return err
101			}
102			pkg := &Package{
103				Format:   packageFormat,
104				Version:  packageVersion,
105				Snapshot: target,
106				Objects:  []PackageObject{},
107			}
108			var baseSnap Snapshot
109			if base != "" {
110				var err error
111				baseSnap, err = s.loadSnapshotRecord(base)
112				if err != nil {
113					return fmt.Errorf("cannot use base snapshot: %w", err)
114				}
115				pkg.Base = &baseSnap
116			}
117	
118			// Verify every object the target references, reading each once. This
119			// includes objects the delta omits because the base references them:
120			// certifying the delta requires those to be intact too. Only objects
121			// the base does not reference are carried. Digests are processed in
122			// sorted order so the package layout and any failure message are
123			// deterministic.
124			carry := digestsReferenced(target.Entries)
125			if base != "" {
126				for digest := range digestsReferenced(baseSnap.Entries) {
127					delete(carry, digest)
128				}
129			}
130			for _, digest := range sortedDigests(target.Entries) {
131				content, size, err := s.readVerifiedObject(digest, target.Entries)
132				if err != nil {
133					return fmt.Errorf("snapshot %q references unusable object %s: %w", name, digest, err)
134				}
135				if _, included := carry[digest]; !included {
136					continue
137				}
138				pkg.Objects = append(pkg.Objects, PackageObject{
139					Digest: digest,
140					Size:   size,
141					Data:   base64.StdEncoding.EncodeToString(content),
142				})
143			}
144	
145			data, err := marshalPackage(pkg)
146			if err != nil {
147				return err
148			}
149			if err := s.writeOutputPackage(pin, absOut, data, mode); err != nil {
150				return err
151			}
152			result = ExportResult{Name: name, Entries: len(target.Entries), Objects: len(pkg.Objects)}
153			return nil
154		})
155		if err != nil {
156			return ExportResult{}, err
157		}
158		return result, nil
159	}
160	
161	// writeOutputPackage stages the package as a complete temporary file inside
162	// the pinned parent directory and commits it via Store.commitOutput, which
163	// revalidates the destination immediately before the atomic rename. On any
164	// failure the temporary file is removed and an existing output is never
165	// touched.
166	func (s *Store) writeOutputPackage(pin *parentPin, absOut string, data []byte, mode os.FileMode) error {
167		tmp, tmpBase, err := createTempIn(pin, ".package-")
168		if err != nil {
169			return fmt.Errorf("cannot create temporary file for output: %w", err)
170		}
171		committed := false
172		defer func() {
173			if !committed {
174				removeTempIn(pin, tmpBase)
175			}
176		}()
177		if err := tmp.Chmod(mode); err != nil {
178			tmp.Close()
179			return fmt.Errorf("cannot prepare output file: %w", err)
180		}
181		if _, err := tmp.Write(data); err != nil {
182			tmp.Close()
183			return fmt.Errorf("cannot write output %q: %w", absOut, err)
184		}
185		if err := tmp.Sync(); err != nil {
186			tmp.Close()
187			return fmt.Errorf("cannot write output %q: %w", absOut, err)
188		}
189		if err := tmp.Close(); err != nil {
190			return fmt.Errorf("cannot write output %q: %w", absOut, err)
191		}
192		if err := s.commitOutput(pin, tmpBase, absOut); err != nil {
193			return err
194		}
195		committed = true
196		_ = syncDirectory(pin.f)
197		return nil
198	}
199	
200	// ImportSnapshot imports a snapshot package produced by ExportSnapshot into an
201	// initialized repository.
202	//
203	// Import only adds the package's snapshot and any missing content objects; it
204	// never changes the current name mapping or any existing snapshot or object.
205	// A delta package is accepted only when the destination already contains a
206	// snapshot with the base name and byte-identical entry metadata, and every
207	// object the delta omits is present and intact. Healthy objects already in the
208	// destination are reused; re-importing a package whose snapshot is already
209	// present with identical metadata succeeds without creating a second copy. A
210	// same-named snapshot with different metadata is refused.
211	//
212	// All validation and reuse happens before anything is written. New objects
213	// land as complete files via temp-file-and-rename, and the snapshot record is
214	// renamed into place only after every object the mapping references has been
215	// verified, so a crash or write failure leaves at most unreferenced complete
216	// objects that a later gc removes and a retry succeeds; a partially imported
217	// snapshot can never be observed.
218	func (s *Store) ImportSnapshot(file string) (ImportResult, error) {
219		if file == "" {
220			return ImportResult{}, errors.New("file is required")
221		}
222		data, err := os.ReadFile(file)
223		if err != nil {
224			return ImportResult{}, err
225		}
226		pkg, err := decodePackage(data)
227		if err != nil {
228			return ImportResult{}, err
229		}
230		// Import targets an initialized repository; it never creates one the way
231		// mutating artifact commands do.
232		rootInfo, err := os.Stat(s.root)
233		switch {
234		case errors.Is(err, os.ErrNotExist):
235			return ImportResult{}, fmt.Errorf("repository %q does not exist; run init first", s.root)
236		case err != nil:
237			return ImportResult{}, err
238		case !rootInfo.IsDir():
239			return ImportResult{}, fmt.Errorf("repository root %q is not a directory", s.root)
240		}
241		var result ImportResult
242		err = s.withLock(true, func() error {
243			if _, err := os.Stat(s.indexPath()); errors.Is(err, os.ErrNotExist) {
244				return fmt.Errorf("repository %q is not initialized; run init first", s.root)
245			} else if err != nil {
246				return err
247			}
248			if err := rejectLinkedDirs(s.root); err != nil {
249				return err
250			}
251	
252			// A delta must sit on an exactly matching base: same snapshot name and
253			// identical entry metadata. A merely same-named snapshot, or objects
254			// that happen to share digests, is not a base.
255			if pkg.Base != nil {
256				existing, err := s.loadSnapshotRecord(pkg.Base.Name)
257				if err != nil {
258					return fmt.Errorf("delta base snapshot %q is unavailable: %w", pkg.Base.Name, err)
259				}
260				if !snapshotsEqual(existing, *pkg.Base) {
261					return fmt.Errorf("delta base snapshot %q does not match the package base", pkg.Base.Name)
262				}
263				if err := s.verifyReferencedObjects(pkg.Base.Name, existing.Entries); err != nil {
264					return fmt.Errorf("delta base snapshot %q is not fully present: %w", pkg.Base.Name, err)
265				}
266			}
267	
268			// A same-named destination snapshot is either identical metadata or a
269			// collision. A collision is refused before anything is staged.
270			targetPath := s.snapshotPath(pkg.Snapshot.Name)
271			identicalSnapshot := false
272			if existing, statErr := os.Lstat(targetPath); statErr == nil {
273				if existing.Mode()&os.ModeSymlink != 0 {
274					return fmt.Errorf("snapshot path %q is a symbolic link", targetPath)
275				}
276				current, err := s.loadSnapshotRecord(pkg.Snapshot.Name)
277				if err != nil {
278					return fmt.Errorf("snapshot %q already exists and is unusable: %w", pkg.Snapshot.Name, err)
279				}
280				if !snapshotsEqual(current, pkg.Snapshot) {
281					return fmt.Errorf("snapshot %q already exists with different metadata; refusing to overwrite", pkg.Snapshot.Name)
282				}
283				identicalSnapshot = true
284				// Fast path: everything the published snapshot needs is already
285				// present and healthy, so the import is a no-op.
286				if s.verifyReferencedObjects(pkg.Snapshot.Name, pkg.Snapshot.Entries) == nil {
287					result = ImportResult{Name: pkg.Snapshot.Name, Entries: len(pkg.Snapshot.Entries), NewObjects: 0}
288					return nil
289				}
290				// Otherwise fall through: a carried object that is merely missing
291				// can be staged to complete an earlier interrupted import, while a
292				// damaged existing object still aborts below.
293			} else if !errors.Is(statErr, os.ErrNotExist) {
294				return statErr
295			}
296	
297			objects, err := pkg.materialize()
298			if err != nil {
299				return err
300			}
301	
302			// Phase 1, no writes: classify every carried object. Existing files
303			// must be healthy and are reused; a damaged one aborts the import and
304			// is reported by digest.
305			toAdd := make([]objectContent, 0, len(objects))
306			for _, obj := range objects {
307				path := s.objectPath(obj.digest)
308				info, err := os.Lstat(path)
309				switch {
310				case err == nil:
311					if info.Mode()&os.ModeSymlink != 0 {
312						return fmt.Errorf("object %s: object path is a symbolic link", obj.digest)
313					}
314					if !info.Mode().IsRegular() {
315						return fmt.Errorf("object %s: object path is not a regular file", obj.digest)
316					}
317					if _, _, err := s.readVerifiedObject(obj.digest, pkg.Snapshot.Entries); err != nil {
318						return fmt.Errorf("object %s already present but damaged: %w", obj.digest, err)
319					}
320				case errors.Is(err, os.ErrNotExist):
321					toAdd = append(toAdd, obj)
322				default:
323					return err
324				}
325			}
326	
327			// Phase 2: stage missing objects as complete, content-addressed files.
328			// A failure here leaves only unreferenced complete objects behind; a
329			// retry reuses them and finishes the import.
330			for _, obj := range toAdd {
331				if err := s.stageObject(obj.digest, obj.content); err != nil {
332					return err
333				}
334			}
335	
336			// Phase 3: the published mapping must be fully restorable. This covers
337			// reused objects, newly staged ones, and everything omitted by a delta.
338			if err := s.verifyReferencedObjects(pkg.Snapshot.Name, pkg.Snapshot.Entries); err != nil {
339				return err
340			}
341	
342			// Phase 4: publish the snapshot record last (unless an identical one is
343			// already published). This rename is the commit point; before it a new
344			// imported snapshot simply does not exist.
345			if !identicalSnapshot {
346				if err := s.saveSnapshot(targetPath, pkg.Snapshot); err != nil {
347					return err
348				}
349			}
350			result = ImportResult{Name: pkg.Snapshot.Name, Entries: len(pkg.Snapshot.Entries), NewObjects: len(toAdd)}
351			return nil
352		})
353		if err != nil {
354			return ImportResult{}, err
355		}
356		return result, nil
357	}
358	
359	// loadSnapshotRecord reads and fully validates one stored snapshot: the path
360	// must be a regular file (never a symlink), the document must be a single
361	// well-formed object, carry a present non-null entries mapping, record the
362	// same name it is filed under (in full), and contain only valid entry records.
363	func (s *Store) loadSnapshotRecord(name string) (Snapshot, error) {
364		path := s.snapshotPath(name)
365		info, err := os.Lstat(path)
366		if errors.Is(err, os.ErrNotExist) {
367			return Snapshot{}, fmt.Errorf("snapshot %q not found", name)
368		}
369		if err != nil {
370			return Snapshot{}, err
371		}
372		if info.Mode()&os.ModeSymlink != 0 {
373			return Snapshot{}, fmt.Errorf("snapshot %q is a symbolic link", name)
374		}
375		if !info.Mode().IsRegular() {
376			return Snapshot{}, fmt.Errorf("snapshot %q is not a regular file", name)
377		}
378		data, err := os.ReadFile(path)
379		if err != nil {
380			return Snapshot{}, err
381		}
382		snap, err := decodeSnapshotRecord(data, name)
383		if err != nil {
384			return Snapshot{}, fmt.Errorf("snapshot %q is corrupted: %w", name, err)
385		}
386		return snap, nil
387	}
388	
389	// verifyReferencedObjects checks each distinct referenced digest once against
390	// the stored object's size and SHA-256.
391	func (s *Store) verifyReferencedObjects(snapshotName string, entries map[string]Entry) error {
392		for _, digest := range sortedDigests(entries) {
393			if _, _, err := s.readVerifiedObject(digest, entries); err != nil {
394				return fmt.Errorf("object %s needed by snapshot %q: %w", digest, snapshotName, err)
395			}
396		}
397		return nil
398	}
399	
400	// readVerifiedObject reads a content object and returns its bytes, confirming
401	// its SHA-256 digest and the size recorded for it in the given entries.
402	func (s *Store) readVerifiedObject(digest string, entries map[string]Entry) ([]byte, int64, error) {
403		path := s.objectPath(digest)
404		info, err := os.Lstat(path)
405		if err != nil {
406			return nil, 0, err
407		}
408		if info.Mode()&os.ModeSymlink != 0 {
409			return nil, 0, errors.New("object path is a symbolic link")
410		}
411		if !info.Mode().IsRegular() {
412			return nil, 0, errors.New("object path is not a regular file")
413		}
414		content, err := os.ReadFile(path)
415		if err != nil {
416			return nil, 0, err
417		}
418		sum := sha256.Sum256(content)
419		if actual := hex.EncodeToString(sum[:]); actual != digest {
420			return nil, 0, fmt.Errorf("content checksum is %s", actual)
421		}
422		// Every entry referencing this digest must agree on the size; a content
423		// hash fixes the byte count, so a disagreement is a corrupt record.
424		for _, entry := range entries {
425			if entry.Digest == digest && int64(len(content)) != entry.Size {
426				return nil, 0, fmt.Errorf("content is %d bytes, record for %q says %d", len(content), entry.Name, entry.Size)
427			}
428		}
429		return content, int64(len(content)), nil
430	}
431	
432	// stageObject writes one missing object to a temp file and renames it into
433	// place. The content digest was verified when the package was decoded, so the
434	// final file is complete before it ever appears under its digest name.
435	func (s *Store) stageObject(digest string, content []byte) error {
436		tmp, err := os.CreateTemp(filepath.Join(s.root, "objects"), ".import-*")
437		if err != nil {
438			return err
439		}
440		tmpName := tmp.Name()
441		defer os.Remove(tmpName)
442		if _, err := tmp.Write(content); err != nil {
443			tmp.Close()
444			return fmt.Errorf("object %s: %w", digest, err)
445		}
446		if err := tmp.Close(); err != nil {
447			return fmt.Errorf("object %s: %w", digest, err)
448		}
449		if err := os.Rename(tmpName, s.objectPath(digest)); err != nil {
450			return fmt.Errorf("object %s: %w", digest, err)
451		}
452		return nil
453	}
454	
455	// rejectLinkedDirs makes sure an import can never stage files outside the
456	// repository through a replaced objects or snapshots directory.
457	func rejectLinkedDirs(root string) error {
458		for _, dir := range []string{filepath.Join(root, "objects"), filepath.Join(root, "snapshots")} {
459			if err := ensureRealDir(dir); err != nil {
460				return err
461			}
462		}
463		return nil
464	}
465	
466	// snapshotsEqual reports whether two snapshot records carry the same snapshot
467	// name and identical metadata for every entry.
468	func snapshotsEqual(a, b Snapshot) bool {
469		return reflect.DeepEqual(a.Entries, b.Entries) && a.Name == b.Name
470	}
471	
472	func sortedDigests(entries map[string]Entry) []string {
473		seen := map[string]struct{}{}
474		for _, entry := range entries {
475			seen[entry.Digest] = struct{}{}
476		}
477		out := make([]string, 0, len(seen))
478		for digest := range seen {
479			out = append(out, digest)
480		}
481		sort.Strings(out)
482		return out
483	}
484

